  'reg_decl_body': [
    'I attend Karuna Sadan Services voluntarily and of my own free will. I am of sound mind and make this decision independently without any coercion, force, or undue influence from any individual, group, or organisation.\n\nI have not received, nor been promised, any gifts, money, employment, better lifestyle, healing, or any other form of benefit or inducement to attend or participate in the Karuna Sadan services. My attendance is solely based on my personal beliefs and my personal spiritual convictions.\n\nI confirm that neither Karuna Sadan nor any of its leaders have exerted any pressure or influence on me to change my religion. I have not changed my religion.\n\nI have read and understood this declaration, and by signing below, I affirm that my decision to attend the service is entirely voluntary and free of any external influence.',
    'मैं करुणा सदन की सभाओं में अपनी इच्छा से और स्वेच्छा से भाग लेता/लेती हूँ। मैं पूरी तरह से मानसिक रूप से स्वस्थ हूँ और यह निर्णय मैंने खुद से लिया है। इस निर्णय के लिए मुझ पर किसी व्यक्ति, समूह या संस्था द्वारा कोई दबाव, ज़बरदस्ती या गलत प्रभाव नहीं डाला गया है।\n\nमुझे करुणा सदन की सभाओं में आने या भाग लेने के लिए न तो कोई उपहार, पैसे, नौकरी, बेहतर जीवन, चंगाई या किसी भी प्रकार का लाभ दिया गया है और न ही ऐसा कोई वादा किया गया है। मैं केवल अपनी व्यक्तिगत मान्यताओं और अपने आत्मिक विश्वास के आधार पर ही इन सभाओं में भाग लेता/लेती हूँ।\n\nमैं पुष्टि करता/करती हूँ कि करुणा सदन या उसके अधिकारियों द्वारा मुझ पर अपना धर्म बदलने के लिए कोई दबाव या प्रभाव नहीं डाला गया है। मैंने अपना धर्म नहीं बदला है।\n\nमैंने इस घोषणा को पढ़ लिया है और समझ लिया है। नीचे हस्ताक्षर करके मैं यह पुष्टि करता/करती हूँ कि सभा में शामिल होने का मेरा निर्णय पूरी तरह से स्वेच्छा से लिया गया है और इस पर किसी भी बाहरी प्रभाव का कोई असर नहीं है।',
    'मी करुणा सदनच्या सभांना माझ्या स्वतःच्या इच्छेने आणि स्वेच्छेने उपस्थित राहतो / राहते. मी पूर्ण शुद्ध मनःस्थितीत असून हा निर्णय मी कोणत्याही व्यक्ती, गट किंवा संस्थेच्या दबाव, जबरदस्ती, प्रलोभन किंवा अनुचित प्रभावाशिवाय स्वतंत्रपणे घेतला आहे.\n\nकरुणा सदनच्या सभांना उपस्थित राहण्यासाठी किंवा त्यामध्ये सहभागी होण्यासाठी मला कोणतीही भेटवस्तू, पैसा, नोकरी, चांगली जीवनशैली, आरोग्यलाभ किंवा इतर कोणत्याही प्रकारचा लाभ अथवा प्रलोभन देण्यात आलेले नाही किंवा त्याचे आश्वासनही देण्यात आलेले नाही. माझी उपस्थिती ही केवळ माझ्या वैयक्तिक श्रद्धा आणि आध्यात्मिक विश्वासांवर आधारित आहे.\n\nमी याची पुष्टी करतो / करते की करुणा सदन किंवा त्याच्या कोणत्याही नेत्यांनी माझ्यावर धर्मपरिवर्तन करण्यासाठी कोणताही दबाव किंवा प्रभाव टाकलेला नाही. मी माझा धर्म बदललेला नाही.\n\nमी हे घोषणापत्र वाचले असून ते मला पूर्णपणे समजले आहे. खाली स्वाक्षरी करून मी हे घोषित करतो / करते की सभेला उपस्थित राहण्याचा माझा निर्णय पूर्णपणे स्वेच्छेने घेतलेला असून त्यावर कोणत्याही बाह्य प्रभावाचा परिणाम नाही.',
    'I attend Karuna Sadan Services voluntarily and of my own free will. I am of sound mind and make this decision independently without any coercion, force, or undue influence from any individual, group, or organisation.\n\nI have not received, nor been promised, any gifts, money, employment, better lifestyle, healing, or any other form of benefit or inducement to attend or participate in the Karuna Sadan services. My attendance is solely based on my personal beliefs and my personal spiritual convictions.\n\nI confirm that neither Karuna Sadan nor any of its leaders have exerted any pressure or influence on me to change my religion. I have not changed my religion.\n\nI have read and understood this declaration, and by signing below, I affirm that my decision to attend the service is entirely voluntary and free of any external influence.',
